preset.warp:
uniform sampler2D sampler_cover;
// The theme's accent, one pixel wide (see the app's
// services/milkdrop/textures.ts).
uniform sampler2D sampler_accent;
vec3 accent() {
  return texture(sampler_accent, vec2(0.5)).rgb;
}
// The screen's shorter side in the square units of (uv - 0.5) * aspect.xy,
// relative to a 16:9 window's: the cover is sized against the height, so a
// 21:9 screen does not blow it up.
float shortSide() {
  return min(aspect.x, aspect.y) / 0.5625;
}
// Half the cover's width, in those units.
float coverHalf() {
  return q2 * shortSide();
}
float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), f.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), f.x), f.y);
}
float potential(vec2 p) {
  return noise(p) + 0.5 * noise(p * 2.13 + 5.2) + 0.25 * noise(p * 4.37 + 1.7);
}
// The smoke's drift: the curl of a slowly changing noise field, which
// swirls it without bunching it up or thinning it out, and a slow push
// away from the cover it comes from.
vec2 drift(vec2 c) {
  vec2 p = c * 3.2 / shortSide() + vec2(q4 * 0.23, -q4 * 0.17);
  vec2 e = vec2(0.02, 0.0);
  float dx = potential(p + e.xy) - potential(p - e.xy);
  float dy = potential(p + e.yx) - potential(p - e.yx);
  vec2 curl = vec2(dy, -dx) / (2.0 * e.x);
  return curl * 0.0011 + c / max(length(c), 0.05) * 0.0005;
}
 shader_body {
  vec2 c = (uv_orig - 0.5) * aspect.xy;
  vec2 from = c - drift(c) * q5;
  vec3 prev = texture(sampler_main, from / aspect.xy + 0.5).rgb;
  // Fading, and by a dithered last step down so that eight bits per
  // channel cannot leave a faint residue standing for good.
  prev = max(prev * 0.99 - hash12(uv_orig * texsize.xy + fract(q4 * 7.0) * 97.0) * 0.004, 0.0);
  // Smoke rising from the cover's edges in the colour of the picture
  // there, in wisps, more of it with every beat.
  float h = coverHalf();
  vec2 cuv = c / (2.0 * h) + 0.5;
  float d = length(max(abs(c) - h, 0.0));
  vec3 edge = textureLod(sampler_cover, clamp(cuv, 0.0, 1.0), 4.0).rgb;
  // Deepened, so the smoke keeps the picture's colour rather than paling
  // to white where it gathers.
  edge = mix(edge, accent() * dot(edge, vec3(0.3, 0.52, 0.18)) * 1.6, 0.25);
  edge = pow(edge, vec3(1.6)) * 1.3;
  float wisps = smoothstep(0.45, 0.85, noise(c * 26.0 / shortSide() + vec2(q4 * 1.7, -q4 * 1.1)));
  float emit = exp(-d * 90.0) * wisps * (0.012 + 0.025 * q6 + 0.02 * q3);
  ret = prev + edge * emit;
 }

preset.comp:
uniform sampler2D sampler_cover;
// The theme's accent, one pixel wide (see the app's
// services/milkdrop/textures.ts).
uniform sampler2D sampler_accent;
vec3 accent() {
  return texture(sampler_accent, vec2(0.5)).rgb;
}
// The screen's shorter side in the square units of (uv - 0.5) * aspect.xy,
// relative to a 16:9 window's: the cover is sized against the height, so a
// 21:9 screen does not blow it up.
float shortSide() {
  return min(aspect.x, aspect.y) / 0.5625;
}
// Half the cover's width, in those units.
float coverHalf() {
  return q2 * shortSide();
}
float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), f.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), f.x), f.y);
}
// The rounded cover's distance, below zero inside.
float coverDist(vec2 c, float h) {
  vec2 q = abs(c) - h + 0.008;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - 0.008;
}
 shader_body {
  float side = shortSide();
  vec2 c = (uv - 0.5) * aspect.xy;
  float h = coverHalf();
  vec2 cuv = c / (2.0 * h) + 0.5;
  float jitter = hash12(uv * texsize.xy);
  // The smoke, soft.
  vec3 smoke = texture(sampler_main, uv).rgb * 0.45 + (texture(sampler_blur1, uv).rgb * scale1 + bias1) * 0.75;
  // Light falling out of the cover through the smoke: along the way back
  // to the middle, what of the picture shines there, scattered by the
  // smoke it passes.
  vec3 shafts = vec3(0.0);
  float weight = 1.0;
  vec2 stepC = -c * (0.75 / 28.0);
  for (int i = 0; i < 28; i++) {
    vec2 p = c + stepC * (float(i) + jitter);
    vec2 puv = p / (2.0 * h) + 0.5;
    float inCover = step(abs(p.x), h) * step(abs(p.y), h);
    vec3 light = textureLod(sampler_cover, clamp(puv, 0.0, 1.0), 3.0).rgb * inCover;
    // Smoke the cover lights from behind sends streaks of its own outwards.
    light += (texture(sampler_blur1, p / aspect.xy + 0.5).rgb * scale1 + bias1) * 0.9 * (1.0 - inCover);
    shafts += light * weight;
    weight *= 0.955;
  }
  shafts /= 28.0;
  float outside = smoothstep(0.0, 0.004, coverDist(c, h));
  float haze = 0.45 + 1.2 * dot(smoke, vec3(0.33));
  vec3 col = smoke * 0.8 + shafts * haze * (2.4 + 0.5 * q3) * outside;
  // Dust drifting through the light, glittering where a shaft catches it.
  vec2 dp = c / side * 34.0 + vec2(q4 * 0.6, q4 * 1.4);
  vec2 cell = floor(dp);
  float dh = hash12(cell);
  vec2 spot = vec2(hash12(cell + 7.1), hash12(cell + 3.3)) * 0.8 + 0.1;
  float mote = exp(-dot(fract(dp) - spot, fract(dp) - spot) * 900.0) * step(0.55, dh);
  col += mote * (0.5 + 0.5 * sin(dh * 50.0 + q4 * 3.0)) * pow(dot(shafts, vec3(0.33)) * 4.0, 2.0) * 1.5 * outside;
  // A soft shadow the cover throws onto the smoke behind it.
  float d = coverDist(c, h);
  float shadowD = coverDist(c - vec2(0.006, 0.014) * side, h);
  col *= 1.0 - 0.75 * exp(-max(shadowD, 0.0) * 55.0 / side) * outside;
  // The cover: sharp, a sheen across it with each beat, and a fine edge
  // of light.
  vec3 cover = texture(sampler_cover, clamp(cuv, 0.0, 1.0)).rgb;
  float sheen = exp(-pow((cuv.x + cuv.y) - 2.4 * q3 + 0.2, 2.0) * 30.0) * 0.12 * q3;
  cover += sheen;
  cover *= 0.94 + 0.06 * (1.0 - cuv.y);
  float pixel = 1.0 / texsize.y;
  float coverCov = clamp(0.5 - d / pixel, 0.0, 1.0);
  float rim = exp(-abs(d) / (1.5 * pixel)) * (0.25 + 0.2 * q3);
  col *= 1.0 - 0.6 * pow(clamp(rad * 1.3, 0.0, 1.0), 2.2);
  col = 1.0 - exp(-col * 1.4);
  // The picture itself untouched by the tone curve and the vignette.
  col = mix(col, cover, coverCov);
  col += mix(accent(), vec3(1.0), 0.5) * rim * 0.35;
  ret = col + (jitter - 0.5) / 255.0;
 }
